import os
import subprocess
import csv
import re
import shutil
import time

# --- Configuration ---
ITERATIONS = 10
ASSEMBLY_DIR = "assembly"
BIN_DIR = "binaries"
OUTPUT_CSV = "benchmark_results.csv"

# The specific versions for your ablation study
# Updated to look for the folders generated by the new bash script!
VERSIONS = [
    "unoptimised",
    "optimised",
    "unoptimised-binary",
    "unoptimised-branches",
    "unoptimised-memory",
    "unoptimised-registers"
]

def run_perf(binary_path):
    """Runs perf stat and extracts hardware metrics + time."""
    # We use sudo because PMU counters usually require root access
    cmd = ["sudo", "perf", "stat", "-e", "instructions,cycles", "-x", ",", binary_path]
    
    start_wall = time.perf_counter()
    result = subprocess.run(cmd, stderr=subprocess.PIPE, stdout=subprocess.DEVNULL, text=True)
    end_wall = time.perf_counter()
    
    instructions, cycles, time_sec = 0, 0, 0.0
    
    # Parse perf output (stderr)
    for line in result.stderr.splitlines():
        parts = line.split(',')
        if len(parts) < 3 or parts[0] == '<not supported>': continue
        
        value = parts[0]
        event = parts[2]
        try:
            if 'instructions' in event: instructions = int(value)
            elif 'cycles' in event: cycles = int(value)
        except ValueError:
            continue
            
    # Bulletproof Regex for "seconds time elapsed"
    # This looks for a decimal number at the start of a line ending in 'seconds time elapsed'
    time_match = re.search(r'([0-9.]+)\s+seconds\s+time\s+elapsed', result.stderr)
    
    if time_match:
        time_sec = float(time_match.group(1))
    else:
        # Fallback to Python's wall-clock if perf doesn't report it
        time_sec = end_wall - start_wall
        
    return instructions, cycles, time_sec

def phase_one_build():
    """Compiles assembly into binaries."""
    print("\n=== PHASE 1: Build & Verify ===")
    master_dir = os.path.join(ASSEMBLY_DIR, "unoptimised")
    if not os.path.exists(master_dir):
        print(f"Error: {master_dir} not found.")
        return []

    benchmarks = [f.replace(".s", "") for f in os.listdir(master_dir) if f.endswith(".s")]
    valid_benchmarks = []

    for bench in benchmarks:
        print(f"Building {bench}...", end=" ", flush=True)
        success = True
        for v in VERSIONS:
            v_dir = os.path.join(BIN_DIR, v)
            os.makedirs(v_dir, exist_ok=True)
            asm = os.path.join(ASSEMBLY_DIR, v, f"{bench}.s")
            output = os.path.join(v_dir, bench)
            
            if not os.path.exists(asm):
                success = False; break
                
            res = subprocess.run(["gcc", "-o", output, asm], capture_output=True)
            if res.returncode != 0:
                success = False; break
        
        if success:
            print("OK")
            valid_benchmarks.append(bench)
        else:
            print("FAILED")
    return valid_benchmarks

def phase_two_benchmark(benchmarks):
    """Runs iterations and saves to CSV."""
    print(f"\n=== PHASE 2: Benchmarking ({ITERATIONS} iterations) ===")
    
    with open(OUTPUT_CSV, mode='w', newline='') as csv_file:
        writer = csv.writer(csv_file)
        writer.writerow(["Benchmark", "Version", "Instructions", "Cycles", "IPC", "Time (sec)"])

        for bench in benchmarks:
            print(f"\n--- {bench} ---")
            for v in VERSIONS:
                bin_path = os.path.join(BIN_DIR, v, bench)
                it_inst, it_cyc, it_time = 0, 0, 0.0
                
                for _ in range(ITERATIONS):
                    inst, cyc, t = run_perf(bin_path)
                    it_inst += inst
                    it_cyc += cyc
                    it_time += t
                
                avg_inst = it_inst // ITERATIONS
                avg_cyc = it_cyc // ITERATIONS
                avg_time = it_time / ITERATIONS
                ipc = avg_inst / avg_cyc if avg_cyc > 0 else 0
                
                writer.writerow([bench, v, avg_inst, avg_cyc, round(ipc, 3), f"{avg_time:.6f}"])
                print(f"  {v:20}: {avg_inst:10} inst | {avg_cyc:10} cyc | {avg_time:.4f}s")

def main():
    if not os.path.exists(ASSEMBLY_DIR):
        print(f"Error: Missing {ASSEMBLY_DIR} folder.")
        return

    valid_benchmarks = phase_one_build()
    if valid_benchmarks:
        phase_two_benchmark(valid_benchmarks)
        print(f"\nResults saved to {OUTPUT_CSV}")
        # Cleanup
        if os.path.exists(BIN_DIR):
            shutil.rmtree(BIN_DIR)

if __name__ == "__main__":
    main()